package ama.api;
import ama.contract.IdentityContracts.*;import ama.contract.MinutesContracts;import ama.minutes.ControlledMinutesDataSource;import ama.meeting.*;import ama.storage.*;import ama.transcript.*;import java.util.*;import java.nio.file.*;import java.util.concurrent.CopyOnWriteArrayList;import com.fasterxml.jackson.databind.ObjectMapper;import org.springframework.core.env.*;import net.bytebuddy.agent.ByteBuddyAgent;import net.bytebuddy.agent.builder.AgentBuilder;import net.bytebuddy.asm.Advice;import static net.bytebuddy.matcher.ElementMatchers.*;
/** Read-only diagnostic of actual public owner projections. Only failure code/call locations escape, never configuration or content. */
public final class LocalPrototypeReadDiagnostic {
 public static final List<String> sites=new CopyOnWriteArrayList<>();
 public static final class FailureSite { @Advice.OnMethodEnter public static void enter(@Advice.Argument(0) MinutesContracts.FailureCode code){if(LocalPrototypeReadDiagnostic.sites.isEmpty())for(var f:Thread.currentThread().getStackTrace())if(f.getClassName().startsWith("ama.")&&!f.getClassName().equals("ama.api.LocalPrototypeReadDiagnostic$FailureSite"))LocalPrototypeReadDiagnostic.sites.add(f.toString());} }
 public static void main(String[] args)throws Exception{
  if(!"1".equals(System.getenv("AMA_LOCAL_DEV"))||args.length!=3)throw new IllegalArgumentException("Owned diagnostic required");UUID.fromString(args[1]);var p=new Properties();try(var in=Files.newInputStream(Path.of(args[0]))){p.load(in);}String url=p.getProperty("database.url");if(url==null||!url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/ama_local_dev\\?.+"))throw new IllegalArgumentException("Dedicated daily database required");
  ByteBuddyAgent.install();new AgentBuilder.Default().disableClassFormatChanges().with(AgentBuilder.RedefinitionStrategy.RETRANSFORMATION).type(named("ama.contract.MinutesContracts")).transform((builder,type,loader,module,domain)->builder.visit(Advice.to(FailureSite.class).on(named("fail")))).installOnByteBuddyAgent();
  var env=new StandardEnvironment();env.getPropertySources().addFirst(new PropertiesPropertySource("daily",p));var source=ControlledMinutesDataSource.create(url,p.getProperty("database.user"),p.getProperty("database.password"));var configured=ConfiguredProcessing.read(env);var output=new LinkedHashMap<String,Object>();
  try(var definitions=ConfiguredBackends.read(env);var client=ConfiguredPublication.read(env,configured.read(),configured.index()).client()){
   var catalog=new FileBackendCatalog(source,definitions.backends(),definitions.defaultId());catalog.configure();var runtime=LocalAcquisitionBudgetCheck.build(source,env,catalog,client);var actor=new Actor("dev-owner",Status.ACTIVE,Set.of(Role.USER));
   for(String name:List.of("current","templates","publicationDeclaration","preparedPublicationDeclaration")){sites.clear();var observation=new LinkedHashMap<String,Object>();try{if(name.equals("current"))runtime.minutes().queries().current(actor,args[1]);else if(name.equals("templates"))runtime.minutes().queries().templates(actor,args[1],20,null);else if(name.equals("preparedPublicationDeclaration"))ama.transcript.LocalPublicationDeclarationDiagnostic.inspectPrepared(runtime.processing().components().authority(),runtime.tx(),runtime.minutes().publications(),args[1]);else ama.transcript.LocalPublicationDeclarationDiagnostic.inspect(runtime.processing().components().authority(),runtime.tx(),args[1]);observation.put("completed",true);}catch(MinutesContracts.Failure failure){observation.put("code",failure.code().name());observation.put("failureSites",List.copyOf(sites));}output.put(name,observation);}
  }
  Files.writeString(Path.of(args[2]),new ObjectMapper().writerWithDefaultPrettyPrinter().writeValueAsString(output));System.out.println(new ObjectMapper().writeValueAsString(output));
 }
}
